// Generated by the ledger's `emit rust`. Rust literals by their full Lean names.
#[macro_export]
macro_rules! ledger {
    // Postcodes in the local delivery area start with this prefix.
    (Shop.Shipping.localPrefix) => {
        "1"
    };
    // Days for local shipping.
    (Shop.Shipping.localDays) => {
        2
    };
    // Days for standard shipping.
    (Shop.Shipping.standardDays) => {
        3
    };
}
